# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">THEME 2: CLASSROOM LIFE — ROUTINES &amp; PREFERENCES</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Study Routines &amp; Learning Activities</text>\n  <text x="180" y="108" text-anchor="middle" font-size="12" fill="#1e3a8a">• review / revise notes (notları gözden geçirmek)</text>\n  <text x="180" y="132" text-anchor="middle" font-size="12" fill="#1e3a8a">• work in pairs / groups (ikili / grup çalışmak)</text>\n  <text x="180" y="156" text-anchor="middle" font-size="12" fill="#1e3a8a">• read silently / aloud (sessiz / sesli okumak)</text>\n  <text x="180" y="180" text-anchor="middle" font-size="12" fill="#1e3a8a">• focus on a task (bir göreve odaklanmak)</text>\n  <text x="180" y="204" text-anchor="middle" font-size="12" fill="#1e3a8a">• take turns / share ideas (sırayla yapmak / paylaşmak)</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Expressing Preferences (+ V-ing)</text>\n  <text x="520" y="110" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">love / enjoy / like + Verb-ing (+)</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" fill="#334155">I enjoy working in groups.</text>\n  <text x="520" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">don\'t like / dislike / hate + Verb-ing (-)</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" fill="#334155">He dislikes reading aloud in class.</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">be good at / interested in + V-ing</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SIMPLE PRESENT VS. PRESENT PROGRESSIVE &amp; QUESTION TAGS</text>\n  <rect x="25" y="55" width="205" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="127" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Simple Present Tense</text>\n  <text x="127" y="105" text-anchor="middle" font-size="11" fill="#713f12">Routines &amp; Habits (Genel)</text>\n  <text x="127" y="128" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">every day, usually, normally</text>\n  <text x="127" y="155" text-anchor="middle" font-size="11" fill="#334155">«She normally studies alone.»</text>\n  <text x="127" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">How often do you revise?</text>\n  <text x="127" y="205" text-anchor="middle" font-size="11" fill="#475569">Twice a week / Every evening.</text>\n  <rect x="247" y="55" width="205" height="180" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Present Progressive</text>\n  <text x="350" y="105" text-anchor="middle" font-size="11" fill="#164e63">Actions Happening Now (Şu an)</text>\n  <text x="350" y="128" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">now, right now, at the moment</text>\n  <text x="350" y="155" text-anchor="middle" font-size="11" fill="#334155">«She is studying with her</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11" fill="#334155">peers right now.»</text>\n  <text x="350" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">am / is / are + V-ing</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Question Tags (Değil mi?)</text>\n  <text x="572" y="108" text-anchor="middle" font-size="11" fill="#581c87">(+) Sentence → (-) Tag</text>\n  <text x="572" y="128" text-anchor="middle" font-size="11" fill="#581c87">(-) Sentence → (+) Tag</text>\n  <text x="572" y="156" text-anchor="middle" font-size="11" fill="#334155">• You review notes, don\'t you?</text>\n  <text x="572" y="180" text-anchor="middle" font-size="11" fill="#334155">• She is marking tests, isn\'t she?</text>\n  <text x="572" y="204" text-anchor="middle" font-size="11" fill="#334155">• He doesn\'t rest, does he?</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NUMBERS (100–500 / 1st–50th), TIME &amp; DATES REVISION</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Cardinal (100–500) &amp; Ordinal (1st–50th)</text>\n  <text x="180" y="108" text-anchor="middle" font-size="12" fill="#7c2d12">• 145: one hundred and forty-five</text>\n  <text x="180" y="130" text-anchor="middle" font-size="12" fill="#7c2d12">• 380: three hundred and eighty</text>\n  <text x="180" y="156" text-anchor="middle" font-size="12" fill="#7c2d12">• 1st (first), 2nd (second), 3rd (third)</text>\n  <text x="180" y="178" text-anchor="middle" font-size="12" fill="#7c2d12">• 20th (twentieth), 21st (twenty-first)</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" fill="#7c2d12">• 30th (thirtieth), 50th (fiftieth)</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Telling the Time &amp; National Dates</text>\n  <text x="520" y="108" text-anchor="middle" font-size="12" fill="#831843">• 08:15 → It is a quarter past eight.</text>\n  <text x="520" y="130" text-anchor="middle" font-size="12" fill="#831843">• 09:30 → It is half past nine.</text>\n  <text x="520" y="152" text-anchor="middle" font-size="12" fill="#831843">• 10:45 → It is a quarter to eleven.</text>\n  <text x="520" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">29th October: Republic Day</text>\n  <text x="520" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">10th November: Atatürk Memorial Day</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
